package com.example.classmanagement.student;
import com.example.classmanagement.classroom.Classroom; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="students") public class Student { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="student_no",nullable=false,unique=true) public String studentNo; @Column(nullable=false) public String name; public String gender; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="class_id") public Classroom classroom; @Column(name="enrollment_date") public LocalDate enrollmentDate; @Column(nullable=false) public String status="在读"; @Column(name="created_at",nullable=false) public LocalDateTime createdAt; @Column(name="updated_at",nullable=false) public LocalDateTime updatedAt; @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} }
